comments.body:
{'type': 'doc', 'version': 1, 'content': [{'type': 'paragraph', 'content': [{'type': 'text', 'text': 'Current Findings:', 'marks': [{'type': 'strong'}]}, {'type': 'hardBreak'}, {'type': 'text', 'text': 'I found upstream tracker issue '}, {'type': 'inlineCard', 'attrs': {'url': 'https://tracker.ceph.com/issues/71347', 'localId': '971b4baeb375'}}, {'type': 'text', 'text': '  where the problematic second check was removed. This second check allowed scrubbing when system load was below the daily average and decreasing, effectively bypassing the first check that respects '}, {'type': 'text', 'text': 'osd_scrub_load_threshold', 'marks': [{'type': 'code'}]}, {'type': 'text', 'text': '. This fallback logic is the root cause of the issue in 8.1. I checked the fix\xa0 is present in ceph-9.0-rhel-patches and ceph-9.1-rhel-patches but missing in ceph-8.1-rhel-patches.'}, {'type': 'hardBreak'}, {'type': 'hardBreak'}, {'type': 'text', 'text': 'https://gitlab.cee.redhat.com/ceph/ceph/-/commit/6d3146bc3709ba82b67b8b47e5eb80bd5045cac3', 'marks': [{'type': 'link', 'attrs': {'href': 'https://gitlab.cee.redhat.com/ceph/ceph/-/commit/6d3146bc3709ba82b67b8b47e5eb80bd5045cac3'}}]}, {'type': 'text', 'text': ' - ceph-9.1-rhel-patches '}], 'attrs': {'localId': 'fabbf38ab531'}}, {'type': 'paragraph', 'content': [{'type': 'text', 'text': 'https://gitlab.cee.redhat.com/ceph/ceph/-/commit/6d3146bc3709ba82b67b8b47e5eb80bd5045cac3', 'marks': [{'type': 'link', 'attrs': {'href': 'https://gitlab.cee.redhat.com/ceph/ceph/-/commit/6d3146bc3709ba82b67b8b47e5eb80bd5045cac3'}}]}, {'type': 'text', 'text': ' - ceph-9.0-rhel-patches'}], 'attrs': {'localId': 'b9ae6f38794c'}}, {'type': 'paragraph', 'content': [{'type': 'text', 'text': 'From ceph-8.1 :', 'marks': [{'type': 'strong'}]}], 'attrs': {'localId': '20b3583e3a42'}}, {'type': 'codeBlock', 'attrs': {'localId': 'd2b489a43728'}, 'content': [{'type': 'text', 'text': 'bool OsdScrub::LoadTracker::scrub_load_below_threshold() const
{
  double loadavgs[3];
  if (getloadavg(loadavgs, 3) != 3) {
    dout(10) << "couldn't read loadavgs" << dendl;
    return false;
  }

  // allow scrub if below configured threshold
  long cpus = sysconf(_SC_NPROCESSORS_ONLN);
  double loadavg_per_cpu = cpus > 0 ? loadavgs[0] / cpus : loadavgs[0];
  if (loadavg_per_cpu < conf->osd_scrub_load_threshold) {
    dout(20) << fmt::format(
		    "loadavg per cpu {:.3f} < max {:.3f} = yes",
		    loadavg_per_cpu, conf->osd_scrub_load_threshold)
	     << dendl;
    return true;
  }

  // allow scrub if below daily avg and currently decreasing
  if (loadavgs[0] < daily_loadavg && loadavgs[0] < loadavgs[2]) {
    dout(20) << fmt::format(
		    "loadavg {:.3f} < daily_loadavg {:.3f} and < 15m avg "
		    "{:.3f} = yes",
		    loadavgs[0], daily_loadavg, loadavgs[2])
	     << dendl;
    return true;
  } <----------------- This is removed 

  dout(10) << fmt::format(
		  "loadavg {:.3f} >= max {:.3f} and ( >= daily_loadavg {:.3f} "
		  "or >= 15m avg {:.3f} ) = no",
		  loadavgs[0], conf->osd_scrub_load_threshold, daily_loadavg,
		  loadavgs[2])
	   << dendl;
  return false;
}'}]}, {'type': 'paragraph', 'content': [{'type': 'text', 'text': 'From 9.1 :', 'marks': [{'type': 'strong'}]}], 'attrs': {'localId': '62727826669d'}}, {'type': 'codeBlock', 'attrs': {'localId': 'e54b294e998f'}, 'content': [{'type': 'text', 'text': 'bool OsdScrub::scrub_load_below_threshold() const
{
  // fetch an up-to-date load average.
  // For the number of CPUs - rely on the last known value, fetched in the
  // 'heartbeat' thread.
  double loadavg;
  if (getloadavg(&loadavg, 1) != 1) {
    loadavg = 0;
  }

  const double loadavg_per_cpu = loadavg / loadavg_cpu_count;
  if (loadavg_per_cpu < conf->osd_scrub_load_threshold) {
    dout(20) << fmt::format(
		    "loadavg per cpu {:.3f} < max {:.3f} (#CPUs:{}) = yes",
		    loadavg_per_cpu, conf->osd_scrub_load_threshold,
		    loadavg_cpu_count)
	     << dendl;
    return true;
  }

  dout(5) << fmt::format(
		  "loadavg {:.3f} >= max {:.3f} (#CPUs:{}) = no",
		  loadavg_per_cpu, conf->osd_scrub_load_threshold,
		  loadavg_cpu_count)
	   << dendl;
  return false;
}'}]}, {'type': 'paragraph', 'content': [{'type': 'text', 'text': 'Currently testing code changes. I will update Jira once testing is done.'}], 'attrs': {'localId': '23f97a4a5e1a'}}]}

