{'type': 'doc', 'version': 1, 'content': [{'type': 'paragraph', 'content': [{'type': 'text', 'text': '[Internal - do not share with customer]', 'marks': [{'type': 'strong'}]}, {'type': 'hardBreak'}, {'type': 'hardBreak'}, {'type': 'text', 'text': "From the initial analysis looks like is_error() function in inventory.py assumes a strict nested dictionary structure (status['status'['health']). However, data from node-proxy cache is sometimes malformed, containing non-dictionary values that cause runtime failure."}], 'attrs': {'localId': '0cd2cf8fc20d'}}, {'type': 'codeBlock', 'attrs': {'localId': '0561206a32f2'}, 'content': [{'type': 'text', 'text': "  def is_error(statuses: ValuesView) -> bool:
