statuses = [
    {'status': ''}  <----------- TypeError: string indices must be integers
]"}]}, {'type': 'codeBlock', 'attrs': {'localId': 'e084be9851f4'}, 'content': [{'type': 'text', 'text': 'Case 2: Top-level string:
statuses = [
    "Error: Connection failed"  <----- TypeError: string indices must be integers
]
'}]}, {'type': 'mediaSingle', 'attrs': {'width': 777, 'widthType': 'pixel', 'localId': '94fb0e6a49aa', 'layout': 'align-start'}, 'content': [{'type': 'media', 'attrs': {'type': 'file', 'id': 'af472348-c333-4080-8fac-25de006a31bd', 'alt': 'image-20260608-114904.png', 'collection': '', 'localId': 'e55352d9e05f', 'height': 851, 'width': 1444}}]}, {'type': 'paragraph', 'content': [{'type': 'text', 'text': "The code fails when accessing ['health'] on a string instead of a dictionary. A possible fix is to add type validation before nested access."}], 'attrs': {'localId': 'fec4d3c206dc'}}, {'type': 'codeBlock', 'attrs': {'localId': '36408bba6cd1'}, 'content': [{'type': 'text', 'text': "def is_error(statuses: ValuesView) -> bool:
    return any(
        isinstance(status, dict) and 
        isinstance(status['status'], dict) and 
        status['status']['health'].lower() == 'error'
        for status in statuses
    )"}]}, {'type': 'paragraph', 'content': [{'type': 'text', 'text': 'Same validation required in is_unknown().'}], 'attrs': {'localId': '89c23b10927e'}}]}

