'}]}, {'type': 'paragraph', 'content': [{'type': 'text', 'text': 'Inside the '}, {'type': 'text', 'text': 'nfs_try_lift_grace()', 'marks': [{'type': 'code'}]}, {'type': 'text', 'text': ' function, '}, {'type': 'text', 'text': 'in_grace', 'marks': [{'type': 'code'}]}, {'type': 'text', 'text': ' is coming as false, and the code is attempting to lift the grace period.'}], 'attrs': {'localId': '4377cb8ae462'}}, {'type': 'codeBlock', 'attrs': {'localId': 'd346164b-f3be-4d95-be08-75a73694cf1d'}, 'content': [{'type': 'text', 'text': 'PTHREAD_MUTEX_lock(&grace_mutex);
